import{_ as t,a}from"./chunks/2026-08-27-r2-diagnostic-review.CA4P3-yJ.js";import{_ as i,C as r,o as l,c as s,E as n,a2 as c}from"./chunks/framework.Cm6XCzck.js";const P=JSON.parse('{"title":"从‘证据不能串账’到动态诊断：CodeFlowMu V2.0.4 如何把研究结论做成工程能力","description":"","frontmatter":{"title":"从‘证据不能串账’到动态诊断：CodeFlowMu V2.0.4 如何把研究结论做成工程能力","date":"2026-08-27","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","research_question":"一个关于证据归属的研究结论，怎样经过工程实现、真实任务校准和生命周期验证，变成可运行、只读、不会替业务裁决签字的诊断能力？","summary":"R2 从 10 条历史 REPORT 中提出‘生命周期位置不能证明证据归属’。这一结论随后进入 CodeFlowMu 工程实现，并在真实任务中持续校准语义，最终成为 V2.0.4 正式版本里会随 active→review 动态重算的证据关联诊断。","sources":"/zh/research/evidence/2026-08-27-r2-v204-evidence-association","project_relevance":"first-party-research","item_id":"RSEM-20260827-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-27-review-status-evidence-association-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-08-27-review-status-evidence-association.md","filePath":"zh/engineering/2026-08-27-review-status-evidence-association.md","lastUpdated":1787899652000}'),p={name:"zh/engineering/2026-08-27-review-status-evidence-association.md"};function d(u,e,R,h,g,E){const o=r("ArticleCover");return l(),s("div",null,[n(o,{image:"/assets/covers/daily-2026-08-27-review-status-evidence-association-cover.png",kicker:"开源工程观察 · 工程研究",title:"从‘证据不能串账’到动态诊断：CodeFlowMu V2.0.4 如何把研究结论做成工程能力",summary:"这不是一项先有产品、再补解释的功能。它从历史证据中的关联问题出发，经过工程实现与真实任务校准，最终成为 V2.0.4 正式版本中的动态证据关联诊断。",version:"RSEM-20260827-02",status:"工程研究 · 2026-08-27",languageHref:"/en/engineering/2026-08-27-review-status-evidence-association",languageLabel:"English"}),e[0]||(e[0]=c(`<h1 id="从-证据不能串账-到动态诊断-codeflowmu-v2-0-4-如何把研究结论做成工程能力" tabindex="-1">从“证据不能串账”到动态诊断：CodeFlowMu V2.0.4 如何把研究结论做成工程能力 <a class="header-anchor" href="#从-证据不能串账-到动态诊断-codeflowmu-v2-0-4-如何把研究结论做成工程能力" aria-label="Permalink to &quot;从“证据不能串账”到动态诊断：CodeFlowMu V2.0.4 如何把研究结论做成工程能力&quot;">​</a></h1><p>这篇文章最初只有一个很小的问题：<strong>一张任务已经进入 <code>review</code>，能不能因此相信它旁边的 REPORT、执行记录和 REVIEW 都属于同一条责任链？</strong></p><p>我们从一份固定历史切片里抽取了 10 条 REPORT 做逐行对账。结果是：4 条可以用显式任务编号直接关联，4 条缺少动作侧任务编号，2 条在两份来源里给出了不同任务编号。</p><p>这组 <code>4 / 4 / 2</code> 从来不是故障率，也不是对 CodeFlowMu 整体质量的评分。它真正逼出的是一个更重要的工程判断：</p><blockquote><p><strong>生命周期位置只能说明任务走到了哪里，不能替证据归属签字。</strong></p></blockquote><p>如果研究停在这里，这只是一条设计原则。真正有价值的是下一步：我们把这个判断做进 CodeFlowMu，并在真实任务运行过程中持续校准证据语义，最终形成 V2.0.4 正式版本中的“证据关联诊断”。</p><p>这条路径不是“发现一个错误，然后补一个功能”，而是：</p><p><strong>研究发现 → 工程设计 → 真实任务校准 → 语义收敛 → 正式发版 → 实机验证。</strong></p><h2 id="_1-理论起点-位置不是归属-关系不能靠猜" tabindex="-1">1. 理论起点：位置不是归属，关系不能靠猜 <a class="header-anchor" href="#_1-理论起点-位置不是归属-关系不能靠猜" aria-label="Permalink to &quot;1. 理论起点：位置不是归属，关系不能靠猜&quot;">​</a></h2><p>最初的 10 条历史样本只使用两类显式事实：动作日志里写 REPORT 时记录的任务编号，以及 REPORT 账本中同一 REPORT 对应的任务编号。</p><p>规则故意很严格：</p><table tabindex="0"><thead><tr><th>两份来源</th><th>输出</th><th>系统不得做什么</th></tr></thead><tbody><tr><td>任务编号都存在且相同</td><td><code>linked</code></td><td>不需要额外推断</td></tr><tr><td>一侧缺少任务编号</td><td><code>missing</code></td><td>不按文件名、时间接近或角色猜归属</td></tr><tr><td>两侧任务编号都存在但不同</td><td><code>conflict</code></td><td>不替用户挑一边当“正确答案”</td></tr></tbody></table><p>公开脱敏样本最终是：<code>linked = 4</code>、<code>missing = 4</code>、<code>conflict = 2</code>。</p><p>它验证的不是 REPORT 内容是否真实，而是读端有没有遵守一条基本纪律：<strong>面对缺失和矛盾，不把不确定性剪掉。</strong></p><p>这个研究结果进一步把“证据链”拆成了多条可以独立核对的关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK / 修订</span></span>
<span class="line"><span>→ attempt</span></span>
<span class="line"><span>→ lease</span></span>
<span class="line"><span>→ execution</span></span>
<span class="line"><span>→ 工具动作证据</span></span>
<span class="line"><span>→ REPORT</span></span>
<span class="line"><span>→ REVIEW / EVAL</span></span>
<span class="line"><span>→ 业务决定</span></span></code></pre></div><p>关键不在箭头多，而在每条箭头都必须回答：<strong>为什么这两个对象可以连在一起？</strong></p><h2 id="_2-从理论到工程-把证据关系做成只读诊断-而不是新的状态机" tabindex="-1">2. 从理论到工程：把证据关系做成只读诊断，而不是新的状态机 <a class="header-anchor" href="#_2-从理论到工程-把证据关系做成只读诊断-而不是新的状态机" aria-label="Permalink to &quot;2. 从理论到工程：把证据关系做成只读诊断，而不是新的状态机&quot;">​</a></h2><p>R2 进入工程实现时，我们没有给任务再加一个“健康/不健康”的总状态，而是做成一个独立、只读的证据关联诊断器。</p><p>它检查的不是“任务成功了吗”，而是：</p><ul><li>当前任务修订能否关联到一次明确的 attempt；</li><li>attempt 能否关联到 lease；</li><li>attempt 能否关联到实际 execution；</li><li>execution 能否关联到工具动作证据；</li><li>REPORT 能否明确回到当前 Task；</li><li>REPORT 能否明确回到正式 REVIEW；</li><li>EVAL 如果存在，它与 REVIEW 是什么关系。</li></ul><p>这套设计有一个非常重要的边界：<strong>诊断器只读取正式事实源并生成派生结果，不改写 TASK、REPORT、REVIEW、lease、attempt 或生命周期。</strong></p><p>它像 X 光机，而不是裁判。</p><h2 id="_3-一个来自-crewai-的独立公开参照-过程不是一个完成事件" tabindex="-1">3. 一个来自 CrewAI 的独立公开参照：过程不是一个完成事件 <a class="header-anchor" href="#_3-一个来自-crewai-的独立公开参照-过程不是一个完成事件" aria-label="Permalink to &quot;3. 一个来自 CrewAI 的独立公开参照：过程不是一个完成事件&quot;">​</a></h2><p>这条研究线并不只在我们的任务账本里出现。CrewAI 的公开工程变更提供了一个很清楚的独立参照。</p><p>João Moura 在 <a href="https://github.com/crewAIInc/crewAI/pull/7115" target="_blank" rel="noreferrer">CrewAI PR #7115</a> 中没有把原来的 deployment 创建事件简单挪到成功之后，而是<strong>保留创建前的 <code>Create Crew Deployment</code> 事件继续记录 creation attempt，再新增一个只有成功后才产生的 <code>Crew Deployment Created</code> 事件，并携带实际返回的 UUID</strong>。该 PR 已于 2026-08-27 合并。</p><p>这个设计为什么重要？因为“尝试创建”和“已经创建成功”是两件不同的事实。如果把原事件直接移到成功之后，历史上的 attempt 指标就会在没有显式声明的情况下变成 success 指标。#7115 明确拒绝这种语义偷换。</p><p>PR 描述还给出一个来源方统计：当时 <code>create_deployment</code> 读取到 76,015 条事件，其中没有一条携带 UUID。这个数字是 CrewAI 作者报告的工程观测，我们没有独立复现，也不把它当作本文自己的实验结果。</p><p>同一作者的 <a href="https://github.com/crewAIInc/crewAI/pull/7118" target="_blank" rel="noreferrer">CrewAI PR #7118</a> 目前仍开放。它尝试为 crew run 增加一个所有用户都可见的 <code>Crew Completed</code> 终态事件，记录 <code>outcome</code> 和 <code>duration_ms</code>，并与已有的起始/创建记录分开。因为它尚未合并，本文只把它当作方向性公开材料，不写成 CrewAI 已交付能力。</p><p>这两条外部材料和 R2 的关系很窄，但很有启发性：</p><blockquote><p><strong>过程中的每一段都需要自己的证据。创建请求不等于创建成功；执行轮次不等于 REPORT 已提交；REPORT 已提交也不等于 REVIEW 已接受。</strong></p></blockquote><p>CrewAI 不是 CodeFlowMu 的实现来源，#7115/#7118 也不证明我们的 R2 设计“正确”。它们的价值是作为独立公开参照，说明另一个 Agent 工程项目也在面对同类的<strong>过程事件、终态事件与可关联标识不能压成一个“完成”事实</strong>的问题。</p><h2 id="_4-开发阶段的真实任务校准-把-什么可以比较-收紧到同一语义域" tabindex="-1">4. 开发阶段的真实任务校准：把“什么可以比较”收紧到同一语义域 <a class="header-anchor" href="#_4-开发阶段的真实任务校准-把-什么可以比较-收紧到同一语义域" aria-label="Permalink to &quot;4. 开发阶段的真实任务校准：把“什么可以比较”收紧到同一语义域&quot;">​</a></h2><p>理论进入代码以后，最重要的工作不是“尽快显示更多关联”，而是用真实任务反复检查：哪些字段真的具有可比性，哪些只是上下文信息，哪些状态是当前阶段本来就不要求。</p><p>开发阶段的真实任务 <code>TASK-20260827-024</code> 对这套语义起了很大的校准作用。</p><p>现场检查让我们明确了几条规则。</p><p>第一，<strong>不同语义域的修订不能直接比较。</strong> 当前文件摘要可以用于缓存和变化检测，但不能自动等价于 attempt 当时记录的业务修订。</p><p>第二，<strong>协作关系不能替代所有权。</strong> 子任务 REPORT 可以包含父任务、关联任务或引用信息，但这些字段不能自动变成 REPORT 的直属归属。</p><p>第三，<strong>还没有在某个存储层物化，不等于执行不存在。</strong> 如果 attempt 已经有正式 <code>session_id</code>，Runtime 事件和回执也能提供同一执行事实，就不能仅因为某个持久化视图尚未落盘而轻率下结论。</p><p>第四，<strong>同一任务同时存在进度报告和最终报告时，必须使用正式锚点。</strong> V2.0.4 使用任务声明的 <code>current_final_report_id</code> 来确定当前正式 REPORT，再与对应 REVIEW 核对。</p><p>这些不是“修补误报”的故事，而是一个新诊断能力在开发过程中必需的语义收敛：<strong>定义清楚什么有资格成为证据，什么有资格成为冲突，什么只能保持未知或不适用。</strong></p><h2 id="_5-v2-0-4-正式发版后的两张实机截图-证明它已经不是静态展示" tabindex="-1">5. V2.0.4 正式发版后的两张实机截图，证明它已经不是静态展示 <a class="header-anchor" href="#_5-v2-0-4-正式发版后的两张实机截图-证明它已经不是静态展示" aria-label="Permalink to &quot;5. V2.0.4 正式发版后的两张实机截图，证明它已经不是静态展示&quot;">​</a></h2><p>V2.0.4 功能完成并正式发版后，我们用同一张真实 QA 任务做了前后观察：</p><p><code>TASK-20260827-030-PM-to-QA</code></p><p>第一张截图时，任务处于 <code>active</code>；第二张截图时，同一任务已经进入 <code>review</code>。</p><p>这两张图最有价值的地方，不是界面多了一块卡片，而是<strong>同一张任务随着生命周期变化，诊断关系自动变化，而且变化与真实流程一致。</strong></p><p>下面两张原始页面截图记录的是<strong>同一张任务</strong>，而不是两份静态示例。第一张展示 <code>active</code> 阶段；第二张展示它进入 <code>review</code> 后的同一块诊断面板。它们是本文的一手界面证据。</p><h3 id="阶段-a-active-——-没有-report-所以-不适用-才是正确答案" tabindex="-1">阶段 A：<code>active</code> —— 没有 REPORT，所以“不适用”才是正确答案 <a class="header-anchor" href="#阶段-a-active-——-没有-report-所以-不适用-才是正确答案" aria-label="Permalink to &quot;阶段 A：\`active\` —— 没有 REPORT，所以“不适用”才是正确答案&quot;">​</a></h3><p>第一张截图中，诊断摘要显示：</p><ul><li>已关联：4</li><li>缺失：0</li><li>冲突：0</li><li>仅旁观：0</li></ul><p>已经能够确认的链路包括：</p><ul><li>任务修订 → attempt：已关联</li><li>attempt → lease：已关联</li><li>attempt → 执行：已关联</li><li>执行 → 工具证据：已关联</li></ul><p>这时任务还在执行阶段，正式 REPORT 尚未产生，所以：</p><ul><li><code>REPORT → Task</code>：<strong>当前阶段不适用</strong></li><li><code>REPORT → REVIEW</code>：<strong>当前阶段不适用</strong></li></ul><p>这不是“缺少证据”，而是<strong>当前阶段本来就不要求这份证据</strong>。</p><p>因此第一张截图里最重要的不是四条绿色关联，而是：</p><blockquote><p><strong><code>missing = 0</code>、<code>conflict = 0</code>。</strong></p></blockquote><p>如果系统在 <code>active</code> 阶段因为没有 REPORT 就报“缺失”，那才是不准确。V2.0.4 在这里正确地区分了“不适用”和“缺失”。</p><p><a href="/joinwell52/assets/figures/2026-08-27-r2-diagnostic-active.png"><img src="`+t+'" alt="同一张 QA 任务处于 active 阶段时的证据关联诊断：四条执行链已关联，REPORT 关系显示当前阶段不适用"></a></p><p><em>图 1：同一张 QA 任务仍在 <code>active</code>。任务修订、attempt、lease、执行和工具证据已能关联；正式 REPORT 尚未产生，因此 REPORT 关系显示“当前阶段不适用”，而不是“缺失”。</em></p><h3 id="阶段-b-review-——-report-与-review-出现后-关系自动转为已关联" tabindex="-1">阶段 B：<code>review</code> —— REPORT 与 REVIEW 出现后，关系自动转为已关联 <a class="header-anchor" href="#阶段-b-review-——-report-与-review-出现后-关系自动转为已关联" aria-label="Permalink to &quot;阶段 B：`review` —— REPORT 与 REVIEW 出现后，关系自动转为已关联&quot;">​</a></h3><p>同一张任务进入 <code>review</code> 后，第二张截图显示：</p><ul><li>attempt → lease：已关联</li><li>attempt → 执行：已关联</li><li>执行 → 工具证据：已关联</li><li>REPORT → Task：已关联</li><li>REPORT → REVIEW：已关联</li></ul><p>这说明正式 REPORT 和 REVIEW 出现以后，诊断器重新读取当前事实，并把原来“不适用”的关系准确转成“已关联”。</p><p>与此同时：</p><ul><li><code>EVAL → REVIEW</code>：<strong>当前阶段不适用 · <code>eval_not_present</code></strong></li></ul><p>这也是正确结果。</p><p>因为这是一张 <strong>QA 任务</strong>。当前工作流里 EVAL 出现在 PM 路径，这张 QA 任务本来就不要求 EVAL 报告。因此 <code>eval_not_present</code> 在这里不是异常，也不是“少了一份材料”，而是角色/流程语义上的正常不适用。</p><p><a href="/joinwell52/assets/figures/2026-08-27-r2-diagnostic-review.png"><img src="'+a+'" alt="同一张 QA 任务进入 review 阶段后的证据关联诊断：REPORT 到 Task 和 REVIEW 均已关联，EVAL 到 REVIEW 显示当前阶段不适用"></a></p><p><em>图 2：同一任务进入 <code>review</code> 后，诊断重算当前正式事实。REPORT → Task 与 REPORT → REVIEW 从先前的不适用变为已关联；EVAL 仍因这条 QA 路径不要求而显示不适用。</em></p><p>所以两张截图合起来证明的是一个很具体的能力：</p><blockquote><p><strong>同一任务的证据要求会随着生命周期和角色变化；诊断也随正式事实变化，并且能够区分“已关联”“缺失/冲突”和“当前阶段不适用”。</strong></p></blockquote><h2 id="_6-不适用-不是弱化版的-缺失-而是必须单独存在的状态" tabindex="-1">6. “不适用”不是弱化版的“缺失”，而是必须单独存在的状态 <a class="header-anchor" href="#_6-不适用-不是弱化版的-缺失-而是必须单独存在的状态" aria-label="Permalink to &quot;6. “不适用”不是弱化版的“缺失”，而是必须单独存在的状态&quot;">​</a></h2><p>很多诊断系统只有“正常 / 异常”。这对 Agent Runtime 不够。</p><p>在长任务系统里，证据要求本身具有阶段性和角色性：</p><ul><li><code>active</code> 阶段没有最终 REPORT，可以完全正常；</li><li>进入 <code>review</code> 后，REPORT 和 REVIEW 才成为当前证据链的一部分；</li><li>QA 任务没有 PM 路径的 EVAL，也可以完全正常。</li></ul><p>因此至少需要区分：</p><ul><li><code>linked</code>：明确稳定键可以证明关系；</li><li><code>missing</code>：当前阶段应该存在，但确实没有找到；</li><li><code>conflict</code>：两个可比较的明确事实互相矛盾；</li><li><code>not_applicable</code>：当前阶段或当前角色本来就不要求；</li><li><code>observer_only</code>：存在旁观核查，但它没有生命周期裁决权。</li></ul><p>这不是 UI 配色问题，而是降低误判成本的语义合同。</p><h2 id="_7-最重要的一句话-证据关联成立-不等于任务已交付" tabindex="-1">7. 最重要的一句话：证据关联成立，不等于任务已交付 <a class="header-anchor" href="#_7-最重要的一句话-证据关联成立-不等于任务已交付" aria-label="Permalink to &quot;7. 最重要的一句话：证据关联成立，不等于任务已交付&quot;">​</a></h2><p>V2.0.4 的诊断区域明确写着：</p><blockquote><p><strong>此结论只描述证据关系，不表示任务已交付或验证通过。</strong></p></blockquote><p>这句话非常重要。</p><p><code>REPORT → REVIEW = 已关联</code> 只证明当前正式 REPORT 和 REVIEW 的稳定键能够对应。</p><p>它不证明：</p><ul><li>REPORT 内容一定真实；</li><li>REVIEW 结论一定正确；</li><li>QA 已经通过；</li><li>ADMIN 已经接受交付；</li><li>任务已经具备进入 <code>done</code> 的条件。</li></ul><p>也就是说：</p><blockquote><p><strong>证据关系是观察事实；交付与验收是另一层裁决。</strong></p></blockquote><p>这也是 CodeFlowMu 一直坚持的证据、执行与裁决分离。</p><h2 id="_8-两个实际操作-让诊断真正进入工程使用" tabindex="-1">8. 两个实际操作，让诊断真正进入工程使用 <a class="header-anchor" href="#_8-两个实际操作-让诊断真正进入工程使用" aria-label="Permalink to &quot;8. 两个实际操作，让诊断真正进入工程使用&quot;">​</a></h2><p>第二张截图里还能看到两个很实用的动作：</p><ul><li><strong>复制对账摘要</strong></li><li><strong>重新检查证据关联</strong></li></ul><p>“复制对账摘要”让 PM 或管理员可以把当前关联结果直接带入后续复核，而不需要重新从日志里拼关系。</p><p>“重新检查证据关联”则意味着诊断不是一次性静态快照。它会重新读取当前正式事实并重新计算，而不是把旧缓存当成永远正确的答案。</p><p>更关键的是，这两个动作仍然不修改正式任务状态。</p><p>因此 V2.0.4 新增的并不是普通“任务详情”，而是一块真正可操作的<strong>证据关联诊断面板</strong>。</p><h2 id="_9-为什么这是一个真实的-研究转工程-案例" tabindex="-1">9. 为什么这是一个真实的“研究转工程”案例 <a class="header-anchor" href="#_9-为什么这是一个真实的-研究转工程-案例" aria-label="Permalink to &quot;9. 为什么这是一个真实的“研究转工程”案例&quot;">​</a></h2><p>这项工作的价值不只是 CodeFlowMu 多了一个功能，而是完整保留了研究进入工程的过程：</p><p><strong>第一步：从历史数据发现问题。</strong> 10 条 REPORT 得到 <code>4 linked / 4 missing / 2 conflict</code>，提出“位置不是归属证明”。</p><p><strong>第二步：把判断转成工程合同。</strong> 把 TASK、attempt、lease、execution、action、REPORT、REVIEW、EVAL 拆成独立关系边。</p><p><strong>第三步：在开发阶段用真实任务校准语义。</strong> 明确哪些 revision 可比较、REPORT ownership 应认哪些稳定键、未物化执行如何读取、最终 REPORT 如何锚定。</p><p><strong>第四步：完成 V2.0.4 工程实现并正式发版。</strong> 诊断能力进入实际产品界面。</p><p><strong>第五步：用同一真实 QA 任务做生命周期前后验证。</strong> <code>active</code> 时 REPORT 关系正确“不适用”；进入 <code>review</code> 后 REPORT → Task / REVIEW 自动变成已关联；EVAL 因 QA 路径本来不要求而继续保持“不适用”。</p><p>这条链最值得保留的地方是：<strong>理论不是写完就结束，工程也不是简单翻译理论。研究结论必须经过真实系统的字段、生命周期、角色和状态语义，最终才能变成可靠的产品能力。</strong></p><h2 id="_10-公开复核-研究样本与-v2-0-4-动态诊断分层保存" tabindex="-1">10. 公开复核：研究样本与 V2.0.4 动态诊断分层保存 <a class="header-anchor" href="#_10-公开复核-研究样本与-v2-0-4-动态诊断分层保存" aria-label="Permalink to &quot;10. 公开复核：研究样本与 V2.0.4 动态诊断分层保存&quot;">​</a></h2><p>完整的 <a href="/joinwell52/zh/research/evidence/2026-08-27-r2-v204-evidence-association">R2 → CodeFlowMu V2.0.4 工程化证据包</a> 已单独公开。</p><p>历史研究证据仍然保留：</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-report-association-fixture.json">10 条脱敏 REPORT 关联样本</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader.mjs">公开 Reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader-check.mjs">公开检查脚本</a></li></ul><p>V2.0.4 动态现场还提供结构化转录：</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-v204-dynamic-diagnostic-snapshots.json">同任务 active / review 两阶段结构化快照</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-v204-dynamic-diagnostic-check.mjs">两阶段一致性检查脚本</a></li></ul><p>本文已嵌入同任务的两张原始页面截图；结构化材料的作用是让截图中可见的阶段、关系状态和 reason code 可以被单独检查。</p><h2 id="结论-真正完成的不是一张诊断卡-而是一条从研究结论到运行能力的链" tabindex="-1">结论：真正完成的不是一张诊断卡，而是一条从研究结论到运行能力的链 <a class="header-anchor" href="#结论-真正完成的不是一张诊断卡-而是一条从研究结论到运行能力的链" aria-label="Permalink to &quot;结论：真正完成的不是一张诊断卡，而是一条从研究结论到运行能力的链&quot;">​</a></h2><p>R2 一开始只想回答：“REPORT 会不会串账？”</p><p>到了 V2.0.4，问题已经变成：</p><p><strong>系统能不能在任务生命周期变化时，持续准确回答当前有哪些证据关系成立、哪些尚未形成、哪些本来就不适用？</strong></p><p>两张同任务的实机截图给出了非常直观的答案：</p><ul><li><code>active</code> 阶段没有 REPORT，诊断正确显示“不适用”；</li><li>进入 <code>review</code> 后，REPORT → Task 和 REPORT → REVIEW 自动变成已关联；</li><li>QA 任务本来不要求 EVAL，因此 EVAL 继续正确显示“不适用”；</li><li>整个诊断只描述证据关系，不越权替交付和验收签字。</li></ul><blockquote><p><strong>证据诊断不是给任务贴一个静态标签，而是随着正式事实变化，持续回答“现在有哪些关系能够被证明”。</strong></p></blockquote><p>这就是这项研究最终变成的工程能力。</p><hr><h2 id="来源与证据边界" tabindex="-1">来源与证据边界 <a class="header-anchor" href="#来源与证据边界" aria-label="Permalink to &quot;来源与证据边界&quot;">​</a></h2><ul><li><a href="https://github.com/crewAIInc/crewAI/pull/7115" target="_blank" rel="noreferrer">CrewAI #7115</a> 已于 2026-08-27 合并。本文只用它作为“creation attempt 与 confirmed creation 必须分开记录”的独立公开工程参照；PR 中的 76,015 条事件与 0 UUID 覆盖率属于来源方报告，本文未独立复现。</li><li><a href="https://github.com/crewAIInc/crewAI/pull/7118" target="_blank" rel="noreferrer">CrewAI #7118</a> 截至本文复核时仍开放。本文只把它作为“独立终态记录”方向的公开材料，不写成已合并或已交付能力。</li><li>CrewAI 与 CodeFlowMu 没有本文所主张的实现继承关系；CrewAI 资料不能证明 R2 正确，R2 也不用于评价 CrewAI 产品质量。</li><li>R2 的历史 <code>4 / 4 / 2</code> 只来自固定的 10 条脱敏 REPORT 样本，不是故障率、总体质量指标或统计结论。</li><li><code>TASK-20260827-024</code> 只用于记录开发阶段对证据语义和正式锚点的现场校准，不把正常开发过程描述成产品故障。</li><li><code>TASK-20260827-030-PM-to-QA</code> 的 active / review 对照来自 V2.0.4 正式版本的同任务本地实机观察，用于说明阶段与角色相关的动态诊断行为。</li><li>本文只在已披露的任务、关系边和可见状态范围内描述能力，不外推为所有任务、所有生命周期组合或全部桌面端 / PWA 路径都已认证。</li></ul>',122))])}const w=i(p,[["render",d]]);export{P as __pageData,w as default};
